#!/usr/bin/env python3
# THE DEUTERONOMY WALK sitting 18 — CHAPTERS 26-28 (LEAN, 2026-09-26; RUN 2): THE CLAIMS of Deuteronomy 26:1-28:69, FIVE manifests for the five draft units, read off
# this sitting's one ledger, every claim LABELED (logic/MIDDOT.md's codes — I1 the a fortiori (qal wa-chomer), I2 the gezerah shavah (the verbal analogy), I3 the
# binyan av (the prototype) — CHECKED IN MIDDOT.md BEFORE THEY WERE TYPED; a code typed only where the row argues by it), a machine check where the ink allows — every
# he_contains substring CUT FROM THE SNAPSHOT STORE'S OWN BYTES by the word's consonants. Claim IDs DV26-, DV27-, DV28A-, DV28B-, DV28C-. Written once (no file may
# exist; the prefixes checked absent). THE SOURCES DISTRIBUTED BY COMPUTATION: every spine piska to the claim whose verse range holds its head (the three headless by
# the ink's seats), every kept outside row by the verse it cites (104:8 by its covenant seat 28:69 — the row counts the covenants, an override named here); every cite
# index name must be used by exactly the claims that own it. Sitting 17's form (write_ch22_manifest.py) over five units. RUN FROM THE REPO ROOT with PYTHONPATH the
# scratchpad.
import json, os, re, sqlite3, glob, subprocess, sys
ROOT = _ROOT
SP = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, SP)
import ch26_ink as I
DATE = I.DATE
db = sqlite3.connect(f'file:{ROOT}/torah_grok.SNAPSHOT-main-51801ca.sqlite?mode=ro', uri=True)
def cut(book, ch, v, word, nth=0):
    rows = db.execute("SELECT w.idx, w.he FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book=? AND v.chapter=? AND v.verse=? ORDER BY w.idx", (book, ch, v)).fetchall()
    plain = lambda h: ''.join(c for c in h if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
    hit = [(i, h) for i, h in rows if plain(h) == word]
    assert len(hit) > nth, (book, ch, v, word, hit)
    idx, he = hit[nth]
    piece = max(he.split('/'), key=len)
    assert len(piece) >= 4, (book, ch, v, word, he.split('/'))
    return idx, piece
def hc(ref, word, note, nth=0):
    b, cv = ref.split(' '); c, v = map(int, cv.split(':'))
    idx, sub = cut(b, c, v, word, nth)
    return {"type": "he_contains", "ref": ref, "idx": idx, "contains": sub, "note": note}
led = open(f'{ROOT}/logic/oral_triage/deu_26_28_ki_tavo_{DATE}.md', encoding='utf-8').read().split('## CITE INDEX')[1]
CI = set(re.findall(r'^(Onkelos Deut \d+:\d+|Sifrei Devarim \d+:\d+)$', led, re.M)); assert len(CI) == 215, len(CI)
HEADV = {298: (26, 2), 299: (26, 3), 303: (26, 13)}
def headv(p): return I.heads[p] if I.heads[p] else HEADV[p]
KEPT = [k for k in I.OUTSIDE if k not in I.EXCLUDED]
SEAT_OF = {(104, 8): (28, 69)}   # the row counts the three covenants — its seat the covenant verse 28:69, not its first cite 28:1 (the English's brackets)
def seat(k): return SEAT_OF.get(k, I.CITED[k][0])
def src(c, lo, hi):
    names = [f'Onkelos Deut {c}:{v}' for v in range(lo, hi + 1)]
    names += [f'Sifrei Devarim {p}:{r}' for p in I.PISKAOT if headv(p)[0] == c and lo <= headv(p)[1] <= hi for r in range(1, I.SPINE_ROWS[p] + 1)]
    names += [f'Sifrei Devarim {p}:{r}' for p, r in KEPT if seat((p, r))[0] == c and lo <= seat((p, r))[1] <= hi]
    for n in names: assert n in CI, n
    return '; '.join(names)
INK = "ink (the lean measure's print asserted in ch26_ink.py — the kin by computation, the formulas' seats over the Torah and the Bible, the parser's hits, the register, the store's mismatches; the Sifrei rows by the codes they carry, the middah codes checked in MIDDOT.md before typing"
def C(cid, c, lo, hi, en, mid, ref, word, note): return {"id": cid, "source": src(c, lo, hi), "ref": f"Deut {c}:{lo}-{hi}" if lo != hi else f"Deut {c}:{lo}", "claim_en": en, "middah": INK + '; ' + mid + ')', "check": hc(ref, word, note)}
